def table(rows, cols=None, maxh='420px', rename=None):
    if not rows: return '<p><i>нет данных</i></p>'
    cols = cols or list(rows[0].keys()); rename = rename or {}
    h = f'<div class="tblwrap" style="max-height:{maxh}"><table class="sortable"><thead><tr>' + ''.join(f'<th>{html.escape(rename.get(c, c))}</th>' for c in cols) + '</tr></thead><tbody>'
    for r in rows:
        h += '<tr>' + ''.join('<td>' + html.escape('—' if str(r.get(c, '')).lower() == 'nan' else str(r.get(c, ''))) + '</td>' for c in cols) + '</tr>'
    return h + '</tbody></table></div>'
