w_sus = dn.get('SUS', {}).get('M0_omega', '—'); w_cus = dn.get('CUS', {}).get('M0_omega', '—')
S1 = f'''<h2 id="b1">1. Резюме этапа B</h2><div class="box key"><ul>
<li><b>Отбор.</b> Перенесённые гены SUS и CUS у грибов находятся под очищающим отбором: ω = {float(w_sus):.2f} и {float(w_cus):.2f} (M0), медианы попарных dN/dS ≈ 0.28–0.29; сайтов под положительным отбором нет. Это функциональные гены, а не разрушающиеся реликты.</li>
<li><b>Структуры.</b> Филогения по структурам белков независимо подтверждает две линии ACS у Boletales (acc-локусная линия монофилетична; «шестёрка» с фрагментом cT-DNA <i>Parasponia</i> вне клады T-DNA acs). Для SUS структурный подход неинформативен.</li>
<li><b>Механизм.</b> Островки собраны из генов опинового метаболизма разных плазмидных источников (опиновые синтазы, опиновые дегидрогеназы, нопалин-синтаза, DUF3830 рядом с <i>mis</i>); пограничных повторов Т-ДНК нет, порядок генов не повторяет Т-область — перенос не был классическим переносом Т-ДНК целиком.</li>
<li><b>Число событий.</b> При одном приобретении на линию потребовалось бы ~30 независимых потерь; для CUS уже доказано ≥2 приобретения. Точный счёт требует видового дерева по генам и более полных сборок.</li>
<li><b>Экспрессия.</b> Открытых RNA-seq для изолятов-носителей нет; в доступных наборах (<i>B. edulis</i>, <i>Butyriboletus subappendiculatus</i>) район островков отсутствует. Вопрос открыт.</li></ul></div>'''
import re, blocks_extra as BX
for blk in (BX.BH, BX.BD, BX.BM, BX.BI, BX.BG): H.append(blk)
hdr = H[:2]; blocks = []; cur = None
for x in H[2:]:
    if x.startswith('<h2 id="b'): cur = [x]; blocks.append(cur)
